-- built-in functions, type affinity, integer/real edge cases, number formatting
SELECT 1 + 1, 7 / 2, 7 % 3, -7 / 2, -7 % 3, 7.0 / 2, 1 / 0, 1.0 / 0, 0.0 / 0;
SELECT 9223372036854775807, 9223372036854775807 + 1, -9223372036854775808, -9223372036854775808 - 1;
SELECT 0.1 + 0.2, 1.0 / 3, 2.0 / 3, 1e308 * 10, -1e308 * 10, 5e-324, 2.2250738585072014e-308;
SELECT 1.7976931348623157e308, 123456789.123456789, 1e15, 1e16, 1e17, 123456789012345678;
SELECT -0.0, 0.0 = -0.0, 100.0, 1e100, 1.5e-7, 3.14159265358979323846;
SELECT printf('%d|%5d|%-5d|%05d|%x|%X|%o|%c', 42, 42, 42, 42, 255, 255, 8, 65);
SELECT printf('%f|%.2f|%10.3f|%e|%.3e|%g|%g|%g', 3.14159, 2.675, -1.5, 12345.678, 0.000123, 1e-5, 123456789.0, 0.1);
SELECT printf('%!.20g|%.17g|%.15g|%a', 0.1, 0.1, 1.0/3, 1.0);
SELECT printf('%s|%10s|%-10s|%.3s|%q|%Q|%Q|%w', 'abc', 'abc', 'abc', 'abcdef', 'it''s', 'it''s', NULL, 'a"b');
SELECT printf('%,d|%lld|%i', 1234567, 123456789012, -5), format('%s=%d', 'x', 3);
SELECT round(2.5), round(-2.5), round(2.675, 2), round(1234.5678, -2), round(1e20, 3);
SELECT abs(-5), abs(-5.5), abs(-9223372036854775807), sign(-3), sign(0), sign(2.5);
SELECT max(1, 2.5, '3'), min('a', 'B', 'c'), coalesce(NULL, NULL, 'z'), ifnull(NULL, 4), nullif(3, 3), iif(1 < 2, 'y', 'n');
SELECT length('héllo'), length(x'00ff'), octet_length('héllo'), upper('héllo abc'), lower('ÀBC Def');
SELECT substr('hello world', 7), substr('hello', -3, 2), substr('héllo', 2, 2), instr('banana', 'na'), replace('banana', 'a', 'o');
SELECT trim('  x  '), ltrim('xxyxx', 'x'), rtrim('xxyxx', 'x'), '[' || char(72, 105, 0x263A) || ']', unicode('€');
SELECT hex('abc'), hex(12345), quote('a''b'), quote(x'0102'), quote(1.5), quote(NULL), unhex('48656C6C6F');
SELECT 'abc' LIKE 'A%', 'abc' GLOB 'A*', 'abc' GLOB 'a?c', 'a_c' LIKE 'a\_c' ESCAPE '\', 'x' BETWEEN 'a' AND 'z';
SELECT typeof(1), typeof(1.0), typeof('1'), typeof(x'01'), typeof(NULL), typeof(1 + '1'), typeof('1' || 1);
SELECT CAST('12abc' AS INTEGER), CAST('1e3' AS INTEGER), CAST('1e3' AS REAL), CAST(3.99 AS INTEGER), CAST(-3.99 AS INTEGER);
SELECT CAST('0x1F' AS INTEGER), 0x1F, CAST(x'414243' AS TEXT), CAST(123 AS BLOB), CAST('  42  ' AS NUMERIC), CAST('4.0' AS NUMERIC);
SELECT 1 << 62, 1 << 63, 1 << 64, -1 >> 1, 5 & 3, 5 | 3, ~5, 6 & -1;
SELECT '10' + 5, '10' || 5, '3.5' * 2, 'abc' + 1, x'31' + 1;
SELECT 10 = '10', 10 = CAST('10' AS INTEGER), 'a' < 'b', 'B' < 'a', 'B' < 'a' COLLATE NOCASE, 1 < 'a', NULL = NULL, NULL IS NULL;
SELECT zeroblob(4), length(zeroblob(1000)), length(randomblob(17)), typeof(random());
SELECT date('2024-02-29', '+1 year'), date('2024-01-31', '+1 month'), date('2024-03-31', '-1 month', 'start of month');
SELECT datetime('2026-11-26 13:45:10', '+90 minutes'), time('23:59:59', '+1 second'), julianday('2000-01-01 12:00:00');
SELECT strftime('%Y-%m-%d %H:%M:%S %j %w %W %s', '2026-11-26 13:45:10.25'), strftime('%f', '2026-11-26 13:45:10.25');
SELECT unixepoch('2026-11-26'), datetime(1795700000, 'unixepoch'), date('2026-11-26', 'weekday 0'), timediff('2026-11-26', '2025-01-01');
SELECT date('2026-02-30'), date('garbage'), datetime('2026-11-26T10:00:00Z'), datetime('2026-11-26 10:00:00+02:00');
SELECT json('{"a":1, "b":[1,2,{"c":null}]}'), json_valid('{"a":'), json_type('[1,2.5,"x",null,true]', '$[1]');
SELECT json_extract('{"a":{"b":[10,20,30]}}', '$.a.b[#-1]'), '{"a":[1,2]}' -> '$.a', '{"a":[1,2]}' ->> '$.a[1]';
SELECT json_array(1, 2.5, 'x', NULL, json('true')), json_object('k', 1, 'l', json_array()), json_quote('a"b');
SELECT json_insert('{"a":1}', '$.b', 2), json_replace('{"a":1}', '$.a', 'z'), json_set('{"a":1}', '$.c[#]', 3), json_remove('[1,2,3]', '$[1]');
SELECT json_patch('{"a":1,"b":2}', '{"b":null,"c":3}'), json_array_length('[1,[2,3],4]'), json_pretty('{"a":[1,{"b":2}]}');
SELECT key, value, type, path FROM json_each('{"x":1,"y":[2,3],"z":{"w":4}}');
SELECT fullkey, atom FROM json_tree('{"x":1,"y":[2,3]}') WHERE atom IS NOT NULL;
SELECT json_group_array(v), json_group_object(k, v) FROM (SELECT 'a' AS k, 1 AS v UNION ALL SELECT 'b', 2.5);
SELECT jsonb('{"a":1}') = jsonb('{"a": 1}'), hex(jsonb('[1]')), json(jsonb('{"x":[1,2]}'));
SELECT total(x), sum(x), avg(x), count(x), count(*) FROM (SELECT 1 AS x UNION ALL SELECT 2.5 UNION ALL SELECT NULL UNION ALL SELECT '4');
SELECT sum(x) FROM (SELECT 9223372036854775807 AS x UNION ALL SELECT 1);
SELECT total(x) FROM (SELECT 9223372036854775807 AS x UNION ALL SELECT 1);
SELECT sqlite_version(), sqlite_source_id() IS NOT NULL, sqlite_compileoption_used('THREADSAFE=0'), sqlite_compileoption_used('OMIT_LOAD_EXTENSION');
SELECT soundex('Robert'), likely(1), unlikely(0), changes(), total_changes(), last_insert_rowid();
SELECT concat('a', NULL, 1, 2.5), concat_ws('-', 'a', NULL, 'b'), octet_length(x'0102'), string_agg('x', ',');
